targets.expr:
sort_desc(topk($TopItems,
  (1 - libvirt_domain_memory_stats_usable_bytes{job=~"libvirt_exporter",os_region=~"$cluster",compute=~"$compute",domain=~"$virtual_machine"}
    / libvirt_domain_info_maximum_memory_bytes{job=~"libvirt_exporter",os_region=~"$cluster",compute=~"$compute",domain=~"$virtual_machine"}) * 100
  * on(domain) group_left(instance_name, project_name)
    max by (domain, instance_name, project_name) (libvirt_domain_openstack_info{job=~"libvirt_exporter",os_region=~"$cluster",compute=~"$compute",domain=~"$virtual_machine"})
))
